#[test]
fn commit_graph_mem_matches_git_commit_count() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_linear_history(5);

    // Get all commit OIDs from git (ground truth)
    let all_commits = rev_list_all(tmp.path());

    // Build in-memory commit graph
    let paths =
        GitRepoPaths::resolve::<RepoOpenError, _>(tmp.path(), &RepoOpenLimits::DEFAULT).unwrap();
    let our_midx_bytes =
        build_midx_bytes(&paths, ObjectFormat::Sha1, &MidxBuildLimits::default()).unwrap();
    let midx = MidxView::parse(our_midx_bytes.as_slice(), ObjectFormat::Sha1).unwrap();

    let tips = rev_list_all(tmp.path());
    let tip_oid = tips.first().unwrap();

    let pack_dirs = collect_pack_dirs(&paths);
    let pack_paths = resolve_pack_paths_from_midx(&midx, &pack_dirs).unwrap();

    let commits =
        load_commits_for_repo(&paths, &midx, &pack_paths, &[*tip_oid], ObjectFormat::Sha1);

    let mem_cg = CommitGraphMem::build(commits, ObjectFormat::Sha1).unwrap();

    // Verify commit counts match git rev-list
    assert_eq!(
        mem_cg.num_commits(),
        all_commits.len() as u32,
        "in-memory commit graph should have same commit count as git rev-list"
    );
}

#[test]
fn commit_graph_mem_all_commits_lookupable() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_linear_history(4);

    let all_commits = rev_list_all(tmp.path());
    assert!(!all_commits.is_empty(), "should have commits");

    // Build in-memory commit graph
    let paths =
        GitRepoPaths::resolve::<RepoOpenError, _>(tmp.path(), &RepoOpenLimits::DEFAULT).unwrap();
    let our_midx_bytes =
        build_midx_bytes(&paths, ObjectFormat::Sha1, &MidxBuildLimits::default()).unwrap();
    let midx = MidxView::parse(our_midx_bytes.as_slice(), ObjectFormat::Sha1).unwrap();

    let pack_dirs = collect_pack_dirs(&paths);
    let pack_paths = resolve_pack_paths_from_midx(&midx, &pack_dirs).unwrap();

    let tip_oid = all_commits.first().unwrap();
    let commits =
        load_commits_for_repo(&paths, &midx, &pack_paths, &[*tip_oid], ObjectFormat::Sha1);

    let mem_cg = CommitGraphMem::build(commits, ObjectFormat::Sha1).unwrap();

    for commit_oid in &all_commits {
        let pos = mem_cg.lookup(commit_oid).unwrap();
        assert!(
            pos.is_some(),
            "commit {commit_oid} should be in in-memory graph"
        );
    }
}

#[test]
fn commit_graph_mem_generation_numbers_valid() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_linear_history(5);

    let paths =
        GitRepoPaths::resolve::<RepoOpenError, _>(tmp.path(), &RepoOpenLimits::DEFAULT).unwrap();
    let our_midx_bytes =
        build_midx_bytes(&paths, ObjectFormat::Sha1, &MidxBuildLimits::default()).unwrap();
    let midx = MidxView::parse(our_midx_bytes.as_slice(), ObjectFormat::Sha1).unwrap();

    let all_commits = rev_list_all(tmp.path());
    let tip_oid = all_commits.first().unwrap();

    let pack_dirs = collect_pack_dirs(&paths);
    let pack_paths = resolve_pack_paths_from_midx(&midx, &pack_dirs).unwrap();

    let commits =
        load_commits_for_repo(&paths, &midx, &pack_paths, &[*tip_oid], ObjectFormat::Sha1);

    let mem_cg = CommitGraphMem::build(commits, ObjectFormat::Sha1).unwrap();

    // Verify generation numbers:
    // - All generations >= 1
    // - Child generation > parent generation
    let mut scratch = ParentScratch::new();

    for commit_oid in &all_commits {
        let pos = mem_cg.lookup(commit_oid).unwrap().unwrap();
        let generation = mem_cg.generation(pos);

        assert!(generation >= 1, "generation should be >= 1");

        mem_cg.collect_parents(pos, 256, &mut scratch).unwrap();
        for parent_pos in scratch.as_slice() {
            let parent_gen = mem_cg.generation(*parent_pos);
            assert!(
                generation > parent_gen,
                "child generation ({generation}) should be > parent generation ({parent_gen})"
            );
        }
    }
}

#[test]
fn commit_graph_mem_parent_relationships_match_git() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_merge();

    let paths =
        GitRepoPaths::resolve::<RepoOpenError, _>(tmp.path(), &RepoOpenLimits::DEFAULT).unwrap();
    let our_midx_bytes =
        build_midx_bytes(&paths, ObjectFormat::Sha1, &MidxBuildLimits::default()).unwrap();
    let midx = MidxView::parse(our_midx_bytes.as_slice(), ObjectFormat::Sha1).unwrap();

    let all_commits = rev_list_all(tmp.path());

    // Get HEAD (merge commit on main) as the tip - this is the most recent commit
    // that can reach all other commits via parent links
    let head_hex = git_output(tmp.path(), &["rev-parse", "HEAD"]);
    let tip_oid = oid_from_hex(&head_hex);

    let pack_dirs = collect_pack_dirs(&paths);
    let pack_paths = resolve_pack_paths_from_midx(&midx, &pack_dirs).unwrap();

    let commits = load_commits_for_repo(&paths, &midx, &pack_paths, &[tip_oid], ObjectFormat::Sha1);

    let mem_cg = CommitGraphMem::build(commits, ObjectFormat::Sha1).unwrap();

    let mut scratch = ParentScratch::new();

    // Verify parent relationships match what git reports
    for commit_oid in &all_commits {
        let commit_hex = format!("{commit_oid}");
        let expected_parents = parent_oids(tmp.path(), &commit_hex);

        let pos = mem_cg.lookup(commit_oid).unwrap().unwrap();
        mem_cg.collect_parents(pos, 256, &mut scratch).unwrap();

        let actual_parent_oids: Vec<OidBytes> = scratch
            .as_slice()
            .iter()
            .map(|p| mem_cg.commit_oid(*p))
            .collect();

        // Sort for comparison since order may differ
        let expected_set: HashSet<_> = expected_parents.into_iter().collect();
        let actual_set: HashSet<_> = actual_parent_oids.into_iter().collect();

        assert_eq!(
            expected_set, actual_set,
            "parent OIDs should match for commit {commit_oid}"
        );
    }
}

// ============================================================================
// End-to-End Correctness Tests
// ============================================================================

struct TestResolver {
    refs: Vec<(Vec<u8>, OidBytes)>,
}

impl StartSetResolver for TestResolver {
    fn resolve(
        &self,
        _paths: &scanner_git::GitRepoPaths,
    ) -> Result<Vec<(Vec<u8>, OidBytes)>, RepoOpenError> {
        Ok(self.refs.clone())
    }
}

struct NoWatermarkStore;

impl RefWatermarkStore for NoWatermarkStore {
    fn load_watermarks(
        &self,
        _repo_id: u64,
        _policy_hash: [u8; 32],
        _start_set_id: [u8; 32],
        ref_names: &[&[u8]],
    ) -> Result<Vec<Option<scanner_git::RefWatermark>>, RepoOpenError> {
        Ok(vec![None; ref_names.len()])
    }
}

#[test]
fn inmem_artifacts_produce_correct_commit_plan() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_linear_history(5);

    let head = git_output(tmp.path(), &["rev-parse", "HEAD"]);
    let tip_oid = oid_from_hex(&head);

    let resolver = TestResolver {
        refs: vec![(b"refs/heads/main".to_vec(), tip_oid)],
    };
    let start_set_id = StartSetConfig::DefaultBranchOnly.id();

    // Open state and build artifacts in-memory
    let mut state = scanner_git::repo_open(
        tmp.path(),
        1,
        [0u8; 32],
        start_set_id,
        &resolver,
        &NoWatermarkStore,
        RepoOpenLimits::DEFAULT,
    )
    .unwrap();

    let limits = ArtifactBuildLimits::default();
    let midx_result = acquire_midx(&mut state, &limits).unwrap();
    let midx_view = MidxView::parse(midx_result.bytes.as_slice(), state.object_format).unwrap();
    let mem_cg =
        acquire_commit_graph(&state, &midx_view, &midx_result.pack_paths, &limits).unwrap();

    // Get planned commits using in-memory CommitGraphMem
    let mem_plan: Vec<u32> = CommitPlanIter::new(&state, &mem_cg, CommitWalkLimits::DEFAULT)
        .unwrap()
        .map(|item| item.unwrap().pos.0)
        .collect();

    // All commits reachable from HEAD should be in the plan (no watermarks set)
    let expected_commits = rev_list_all(tmp.path());
    assert_eq!(
        mem_plan.len(),
        expected_commits.len(),
        "in-memory plan should include all commits reachable from HEAD"
    );

    let mem_oids: HashSet<OidBytes> = mem_plan
        .iter()
        .map(|&pos| mem_cg.commit_oid(gix_commitgraph::Position(pos)))
        .collect();

    let expected_oids: HashSet<OidBytes> = expected_commits.into_iter().collect();

    assert_eq!(
        expected_oids, mem_oids,
        "in-memory plan should produce the same commit OIDs as git rev-list"
    );
}

#[test]
fn acquire_commit_graph_errors_when_start_set_empty_but_refs_exist() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_linear_history(3);
    let git_dir = tmp.path().join(".git");
    let objects_dir = git_dir.join("objects");

    // Simulate missing maintenance artifacts so this path relies on in-memory builds.
    let _ = fs::remove_file(objects_dir.join("pack").join("multi-pack-index"));
    let _ = fs::remove_file(objects_dir.join("info").join("commit-graph"));
    let _ = fs::remove_file(
        objects_dir
            .join("info")
            .join("commit-graphs")
            .join("commit-graph-chain"),
    );

    let resolver = TestResolver { refs: vec![] };
    let start_set_id = StartSetConfig::DefaultBranchOnly.id();
    let mut state = scanner_git::repo_open(
        tmp.path(),
        1,
        [0u8; 32],
        start_set_id,
        &resolver,
        &NoWatermarkStore,
        RepoOpenLimits::DEFAULT,
    )
    .unwrap();

    let limits = ArtifactBuildLimits::default();
    let midx_result = acquire_midx(&mut state, &limits).unwrap();
    let midx_view = MidxView::parse(midx_result.bytes.as_slice(), state.object_format).unwrap();

    let err = acquire_commit_graph(&state, &midx_view, &midx_result.pack_paths, &limits)
        .expect_err("empty start-set on a repo with refs must fail explicitly");
    assert!(
        matches!(err, ArtifactAcquireError::EmptyStartSetWithRefs),
        "unexpected error: {err:?}"
    );
}

#[test]
fn acquire_commit_graph_loads_loose_tip_chain_not_in_midx() {
    if !git_available() {
        eprintln!("git not available; skipping");
        return;
    }

    let tmp = create_repo_with_linear_history(1);
    run_git(tmp.path(), &["commit", "--allow-empty", "-m", "loose-1"]);
    run_git(tmp.path(), &["commit", "--allow-empty", "-m", "loose-2"]);

    let loose_head = oid_from_hex(&git_output(tmp.path(), &["rev-parse", "HEAD"]));
    let loose_parent = oid_from_hex(&git_output(tmp.path(), &["rev-parse", "HEAD~1"]));
    let packed_base = oid_from_hex(&git_output(tmp.path(), &["rev-parse", "HEAD~2"]));

    let resolver = TestResolver {
        refs: vec![(b"refs/heads/main".to_vec(), loose_head)],
    };
    let start_set_id = StartSetConfig::DefaultBranchOnly.id();
    let mut state = scanner_git::repo_open(
        tmp.path(),
        2,
        [0u8; 32],
        start_set_id,
        &resolver,
        &NoWatermarkStore,
        RepoOpenLimits::DEFAULT,
    )
    .unwrap();

    let limits = ArtifactBuildLimits::default();
    let midx_result = acquire_midx(&mut state, &limits).unwrap();
    let midx_view = MidxView::parse(midx_result.bytes.as_slice(), state.object_format).unwrap();

    assert!(
        midx_view.find_oid(&loose_head).unwrap().is_none(),
        "fixture expects loose HEAD commit to be absent from MIDX"
    );
    assert!(
        midx_view.find_oid(&loose_parent).unwrap().is_none(),
        "fixture expects loose parent commit to be absent from MIDX"
    );
    assert!(
        midx_view.find_oid(&packed_base).unwrap().is_some(),
        "fixture expects packed base commit to be present in MIDX"
    );

    let cg = acquire_commit_graph(&state, &midx_view, &midx_result.pack_paths, &limits)
        .expect("loose-tip chain should load via loose-object fallback");
    let expected_commits = rev_list_all(tmp.path());

    assert_eq!(cg.num_commits(), expected_commits.len() as u32);
    for oid in &expected_commits {
        assert!(
            cg.lookup(oid).unwrap().is_some(),
            "expected commit {oid} to be present in in-memory graph"
        );
    }
}

